<template>
 <main class="inspection" v-loading="busy">
  <header><div><small>门店运营 / 巡检跟进</small><h1>巡检与整改</h1><p>保留巡店报告原文，确认整改清单后逐项跟进。</p></div><div class="actions"><el-button @click="load">刷新</el-button><el-button v-if="options.can_configure" @click="settings=true">AI设置</el-button><el-button v-if="options.stores?.some(s=>s.can_create)" type="primary" @click="beginCreate">写巡检报告</el-button></div></header>
  <template v-if="!record"><div class="summary"><article><b>{{rows.length}}</b>份巡检报告</article><article><b>{{rows.filter(r=>r.status==='rectifying').length}}</b>份整改中</article><article><b>{{rows.filter(r=>r.status==='final_review').length}}</b>份待最终确认</article></div><div class="filters"><el-input v-model="keyword" placeholder="搜索报告或门店" clearable/><el-select v-model="status" placeholder="全部状态" clearable><el-option v-for="(v,k) in reportLabels" :key="k" :label="v" :value="k"/></el-select><StoreRegionSelect v-model="storeFilter" :stores="options.stores" restrict-to-stores placeholder="全部门店" clearable/></div>
   <el-table :data="filtered" @row-click="open"><el-table-column prop="title" label="巡检报告" min-width="220"/><el-table-column prop="store_name" label="门店" min-width="180"/><el-table-column prop="author_name" label="督导" width="110"/><el-table-column label="状态" width="140"><template #default="{row}">{{reportLabels[row.status]}}</template></el-table-column><el-table-column label="整改进度" min-width="180"><template #default="{row}"><span v-if="!row.total">{{row.status==='closed'?'无需整改':'待确认清单'}}</span><template v-else><el-progress :percentage="row.percent"/><small>已通过 {{row.approved}} / {{row.total}} · 超期 {{row.overdue}}</small></template></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click.stop="open(row)">查看跟进</el-button></template></el-table-column></el-table>
  </template>
  <template v-else><div class="actions"><el-button @click="record=null">返回报告列表</el-button><el-button v-if="record.can_delete" type="danger" plain @click="deleting=true">删除本人报告</el-button></div><section class="report-head"><div><h2>{{record.title}}</h2><div class="report-meta"><p>门店名称：{{record.store_name}}</p><p>巡店日期：{{record.report_fields.inspection_date}}</p><p>督导：{{record.report_fields.supervisor_name}}</p><p>整改截止时间：{{record.report_fields.deadline_at?format(record.report_fields.deadline_at):(record.report_fields.deadline_hint||'待手动填写')}}</p><p>日报发送日期：{{record.sent_date||'未发送（草稿）'}}</p><p>整改开始时间：{{record.started_at?format(record.started_at):(record.status==='closed'&&!record.total?'无需整改':'未开始（发送后自动记录）')}}</p><p v-if="record.cc_recipients?.length">抄送：{{record.cc_recipients.map(p=>p.name).join('、')}}</p><p>草稿创建：{{format(record.created_at)}}</p></div><el-tag>{{reportLabels[record.status]}}</el-tag></div><div><strong>{{record.total?record.percent+'%':'—'}}</strong><p>复核通过 {{record.approved}} / {{record.total}}<br/>执行超期 {{record.overdue-record.review_overdue}} · 待复核超期 {{record.review_overdue}}</p></div></section>
   <el-tabs v-model="tab"><el-tab-pane label="整改清单" name="items"><el-alert v-if="record.analysis_error" :title="record.analysis_error" type="warning" :closable="false"/><div v-if="record.can_edit" class="actions"><el-button @click="analyze">AI识别原文</el-button><el-button @click="addItem">手动增加整改项</el-button><el-button @click="save">保存清单</el-button><el-button type="primary" @click="publish">确认并下发 / 无需整改归档</el-button></div><div v-if="record.can_edit" class="actions"><label>抄送人员</label><el-select v-model="record.cc_user_ids" multiple filterable :multiple-limit="30"><el-option v-for="p in options.cc_people||[]" :key="p.id" :value="p.id" :label="p.name+(p.position?'（'+p.position+'）':'')"/></el-select></div><p v-if="record.can_edit" class="muted">AI只是草稿。核对原文、删除重复事项，建议和已完成事项默认不下发。默认截止到当天23:59:59，可手动调整日期；按北京时间计算。</p>
    <el-empty v-if="!record.items.length" description="暂无整改项；可以手动添加，也可确认无需整改后归档"/>
    <article v-for="(item,index) in record.items" :key="item.id||index" class="item"><div class="item-head"><h3>{{index+1}}. {{item.title||'新整改项'}}</h3><el-tag>{{record.can_edit?kindLabels[item.kind]:itemLabels[item.status]}}</el-tag></div><template v-if="record.can_edit"><el-checkbox v-model="item.selected">纳入整改清单</el-checkbox><el-select v-model="item.kind"><el-option v-for="(v,k) in kindLabels" :key="k" :label="v" :value="k"/></el-select><el-input v-model="item.title" maxlength="120" placeholder="整改标题"/><el-input v-model="item.action" type="textarea" :rows="3" maxlength="3000" placeholder="整改要求和验收标准"/><div class="item-fields"><label>执行人（可由店长再分配）<el-select v-model="item.assignee_id" clearable><el-option v-for="p in record.executors" :key="p.id" :value="p.id" :label="p.name"/></el-select></label><label>复核人<el-select v-model="item.reviewer_id" clearable><el-option v-for="p in record.reviewers" :key="p.id" :value="p.id" :label="p.name"/></el-select></label><label>截止日期（当天结束）<el-date-picker :model-value="dateKey(item.due_at||record.report_fields.deadline_at)" @update:model-value="item.due_at=$event;item.due_inherited=false" type="date" value-format="YYYY-MM-DD" :clearable="false"/></label></div><el-button type="danger" link @click="record.items.splice(index,1)">移除此草稿项</el-button></template><p v-else>{{item.action}}</p>
     <blockquote v-if="item.quote">原文依据：{{item.quote}}</blockquote><p v-if="item.due_hint" class="muted">原文时间要求：{{item.due_hint}}</p><p v-if="!record.can_edit">执行人：{{item.assignee_name||'待店长分配'}}　复核人：{{item.reviewer_name}}　截止：{{format(item.due_at)}} <el-tag v-if="item.overdue" type="danger">{{item.status==='pending_review'?'待复核超期':'执行超期'}}</el-tag></p>
     <div class="actions" v-if="!record.can_edit"><template v-if="record.can_assign&&!['approved','pending_review'].includes(item.status)"><el-select v-model="assignments[item.id]" placeholder="选择执行人"><el-option v-for="p in record.executors" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-button @click="change('assign',item,{assignee_id:assignments[item.id]})">分配</el-button></template><template v-if="record.can_assign&&item.status!=='approved'"><el-select v-model="reviewAssignments[item.id]" placeholder="调整复核人"><el-option v-for="p in record.reviewers" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-button @click="change('reassign_reviewer',item,{reviewer_id:reviewAssignments[item.id]})">调整复核人</el-button></template><el-button v-if="item.can_execute" @click="executeItem=item;submission={note:'',photos:[]}">提交整改</el-button><template v-if="item.can_review"><el-button type="success" @click="review(item,true)">复核通过</el-button><el-button type="danger" @click="review(item,false)">退回重做</el-button></template></div>
     <el-collapse v-if="item.submissions?.length"><el-collapse-item :title="'举证及复核记录（'+item.submissions.length+'版）'"><div v-for="s in item.submissions" :key="s.version" class="submission"><b>第{{s.version}}次提交 · {{format(s.submitted_at)}}</b><p>{{s.note}}</p><el-button v-for="(photo,n) in s.photos" :key="photo" link type="primary" @click="viewPhoto(photo)">查看照片{{n+1}}</el-button><p>{{itemLabels[s.status]||'待复核'}} {{s.review_note}} {{format(s.reviewed_at)}}</p></div></el-collapse-item></el-collapse>
    </article><el-button v-if="record.can_close" type="primary" @click="change('close')">全部复核通过，督导最终确认归档</el-button>
   </el-tab-pane><el-tab-pane label="巡店原文与正向记录" name="original"><template v-if="record.can_edit"><el-input v-model="record.title" maxlength="120" aria-label="报告标题"/><el-input v-model="record.original" type="textarea" :rows="14" maxlength="30000"/><el-button @click="saveOriginal">保存修改后的原文</el-button><p class="muted">修改原文会清空旧拆解清单，需要重新识别或手动整理。</p></template><pre v-else>{{record.original}}</pre><h3>报告配图</h3><el-button v-for="(path,n) in record.report_photos" :key="path" @click="viewPhoto(path)">查看图片{{n+1}}</el-button><label v-if="record.can_edit" class="file-link">添加报告图片（最多9张）<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="addReportPhotos"/></label><div v-if="record.can_edit" class="actions"><el-button v-for="(path,n) in record.report_photos" :key="path" type="danger" link @click="removeReportPhoto(path)">移除图片{{n+1}}</el-button></div><h3>正向记录</h3><p v-if="!record.highlights.length" class="muted">暂无单独记录；原文完整保留</p><blockquote v-for="(h,i) in record.highlights" :key="i">{{h.text}}<p>原文：{{h.quote}}</p></blockquote></el-tab-pane><el-tab-pane label="跟进时间线" name="history"><el-timeline><el-timeline-item v-for="h in record.history" :key="h.id" :timestamp="format(h.created_at)">{{h.actor_name}} · {{h.action}}</el-timeline-item></el-timeline></el-tab-pane></el-tabs>
  </template>
  <NotificationDialog v-model="deleting" title="永久删除报告" tone="danger" subtitle="删除后无法恢复，不进入回收站或归档。"><p>将永久删除本报告原文、报告图片、整改举证、跟进记录和相关通知。门店与抄送人员将无法继续查看。</p><template #footer><el-button :disabled="busy" @click="deleting=false">取消</el-button><el-button type="danger" :loading="busy" @click="deleteReport">永久删除</el-button></template></NotificationDialog>
  <el-dialog v-model="creating" title="写巡检报告" width="min(720px,94vw)"><el-form label-position="top"><el-form-item label="门店"><StoreRegionSelect v-model="draft.store_id" :stores="options.stores?.filter(s=>s.can_create)" restrict-to-stores /></el-form-item><el-form-item label="报告标题"><el-input v-model="draft.title" maxlength="120"/></el-form-item><el-form-item label="巡店报告原文"><el-input v-model="draft.original" type="textarea" :rows="12" maxlength="30000" show-word-limit/></el-form-item><el-form-item label="督导（必填）"><el-input v-model="draft.supervisor_name" maxlength="80"/></el-form-item><el-form-item label="抄送人员"><el-select v-model="draft.cc_user_ids" multiple filterable :multiple-limit="30" placeholder="选择抄送人员"><el-option v-for="p in options.cc_people||[]" :key="p.id" :value="p.id" :label="p.name+(p.position?'（'+p.position+'）':'')"/></el-select></el-form-item><label class="file-link">报告配图（最多9张）<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="chooseDraftPhotos"/></label><p v-for="(file,n) in draftPhotos" :key="n">{{file.name}} <el-button link type="danger" @click="draftPhotos.splice(n,1)">移除</el-button></p><p class="muted">原文与配图完整保留；AI只识别文字。抄送人员可查看报告和进度，不增加办理权限。</p></el-form><template #footer><el-button @click="creating=false">取消</el-button><el-button type="primary" @click="create">保存原文并整理清单</el-button></template></el-dialog>
  <el-dialog v-model="settings" title="巡检AI设置" width="min(640px,94vw)"><el-alert title="默认关闭。启用前核实模型提供方、境内处理和留存规则，并同步隐私声明；可随时使用手动拆解。" type="warning" :closable="false"/><el-form label-position="top"><el-form-item label="启用文本拆解"><el-switch v-model="aiConfig.enabled"/></el-form-item><el-form-item label="企业已配置的模型"><el-select v-model="aiConfig.profile_id"><el-option v-for="p in aiConfig.profiles" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="用户处理告知（提供方、用途、地域、保留规则与隐私链接）"><el-input v-model="aiConfig.disclosure" type="textarea" :rows="6"/></el-form-item></el-form><template #footer><el-button @click="settings=false">取消</el-button><el-button type="primary" @click="run(async()=>{aiConfig=await api.saveConfig(aiConfig);settings=false})">保存设置</el-button></template></el-dialog>
  <el-dialog :model-value="!!executeItem" @close="executeItem=null" title="提交整改举证" width="min(600px,94vw)"><label>整改说明</label><el-input v-model="submission.note" type="textarea" :rows="4" maxlength="3000"/><label class="file-link">上传整改照片（最多9张）<input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="upload"/></label><p>已上传 {{submission.photos.length}} 张；提交后等待指定人员复核。</p><template #footer><el-button @click="executeItem=null">取消</el-button><el-button type="primary" @click="submit">提交复核</el-button></template></el-dialog>
  <el-dialog v-model="photoOpen" title="巡检图片"><img :src="photoUrl" class="photo" alt="巡检报告或整改举证图片"/></el-dialog>
 </main>
</template>
<script setup>
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
import {ref,computed,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
const route=useRoute(),router=useRouter()
import {ElMessage,ElMessageBox} from 'element-plus'
import {inspectionApi as api} from '../api'
import NotificationDialog from '../components/NotificationDialog.vue'
import {readTaskPhoto} from '../../../miniprogram/src/common/cloud-photo-transfer.mjs'
const deleting=ref(false)
const busy=ref(false),rows=ref([]),options=ref({}),record=ref(null),keyword=ref(''),status=ref(''),storeFilter=ref(null),tab=ref('items'),creating=ref(false),settings=ref(false),aiConfig=ref({}),assignments=ref({}),reviewAssignments=ref({}),executeItem=ref(null),submission=ref({note:'',photos:[]}),photoOpen=ref(false),photoUrl=ref(''),draft=ref({title:'巡店日报',store_id:null,original:'',supervisor_name:'',cc_user_ids:[]}),draftPhotos=ref([])
const reportLabels={draft:'待确认草稿',rectifying:'整改中',final_review:'待督导最终确认',closed:'已归档'},kindLabels={action:'需整改',suggestion:'建议（默认不下发）',completed:'已完成（默认不下发）'},itemLabels={unassigned:'待分配',pending:'待整改',doing:'整改中',rejected:'退回整改',pending_review:'待复核',approved:'已通过'}
const filtered=computed(()=>rows.value.filter(r=>(!storeFilter.value||r.store_id===storeFilter.value)&&(!status.value||r.status===status.value)&&(!keyword.value||(r.title+r.store_name).includes(keyword.value))))
const dateKey=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')?v:v?new Date(new Date(v).getTime()+8*3600000).toISOString().slice(0,10):''
const format=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):''
async function run(fn){if(busy.value)return;busy.value=true;try{await fn()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.error||e.message||'操作失败')}finally{busy.value=false}}
async function load(){await run(async()=>{const [o,l,c]=await Promise.all([api.options(),api.list(),api.config()]);options.value=o;rows.value=l.rows;aiConfig.value=c;if(record.value||Number(route.query.id))record.value=(await api.detail(record.value?.id||Number(route.query.id))).record})}
async function open(row){await run(async()=>{record.value=(await api.detail(row.id)).record;tab.value='items'})}
function beginCreate(){draft.value.supervisor_name=options.value.current_actor?.name||'';creating.value=true}
function fileSource(file){return {size:file.size,mime:file.type.replace('image/',''),read:(offset,length)=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file.slice(offset,offset+length))})}}
function chooseDraftPhotos(event){const files=[...event.target.files];event.target.value='';if(files.length+draftPhotos.value.length>9)return ElMessage.error('报告配图最多9张');draftPhotos.value.push(...files)}
async function persistPhotos(files){const paths=[...(record.value.report_photos||[])];if(paths.length+files.length>9)throw Error('报告配图最多9张');let uploadError;for(const file of files){try{paths.push((await api.upload(record.value.id,fileSource(file))).path)}catch(e){uploadError=e;break}}if(paths.length!==record.value.report_photos.length)record.value=(await api.change(record.value.id,'draft',{...payload(),report_photos:paths})).record;if(uploadError)throw Error('部分图片上传失败，成功图片已保存：'+uploadError.message)}
async function addReportPhotos(event){const files=[...event.target.files];event.target.value='';await run(()=>persistPhotos(files))}
async function removeReportPhoto(path){await run(async()=>{await ElMessageBox.confirm('确认从报告中移除此图片？','移除报告图片');record.value=(await api.change(record.value.id,'draft',{...payload(),report_photos:record.value.report_photos.filter(p=>p!==path)})).record})}
function payload(){return {revision:record.value.revision,items:record.value.items,cc_user_ids:record.value.cc_user_ids||[],report_photos:record.value.report_photos||[]}}
async function create(){await run(async()=>{if(!draft.value.supervisor_name.trim())throw Error('请填写督导姓名');const out=await api.create(draft.value);record.value=out.record;creating.value=false;tab.value='original';if(out.duplicate){ElMessage.info('已存在相同报告，已打开原记录');return}await persistPhotos(draftPhotos.value);draftPhotos.value=[]})}
function addItem(){record.value.items.push({title:'',action:'',kind:'action',selected:true,quote:'',due_hint:'',assignee_id:null,reviewer_id:null,due_at:null})}
async function saveOriginal(){await run(async()=>{await ElMessageBox.confirm('原文修改将清空现有拆解草稿，继续保存？','修改原文');record.value=(await api.change(record.value.id,'draft',{...payload(),original:record.value.original,title:record.value.title,items:record.value.items})).record})}
async function save(){await run(async()=>record.value=(await api.change(record.value.id,'draft',payload())).record)}
async function publish(){await run(async()=>{await ElMessageBox.confirm('请核对整改项、责任人与截止日期。下发后原文和清单将锁定；零项则归档为无需整改。','确认清单');if(record.value.items.some(i=>i.selected&&i.kind!=='action'))throw Error('请先核对建议/已完成事项，确需整改时将其分类改为“需整改”');record.value=(await api.change(record.value.id,'draft',payload())).record;record.value=(await api.change(record.value.id,'publish',{revision:record.value.revision,confirmed:true})).record})}
async function analyze(){await run(async()=>{const cfg=await api.config();if(!cfg.enabled)throw Error('AI尚未启用，可手动增加整改项；管理员可在AI设置配置');await ElMessageBox.confirm(cfg.disclosure+'\n仅发送本报告文字；自动遮盖连续号码但不能保证识别全部个人资料，请先移除无关及敏感信息。重新识别会替换当前草稿清单。','AI文本处理告知',{confirmButtonText:'同意并识别',cancelButtonText:'取消',type:'warning'});try{record.value=(await api.change(record.value.id,'analyze',{revision:record.value.revision,consent:true,consent_version:cfg.version})).record}catch(e){record.value=(await api.detail(record.value.id)).record;throw e}})}
async function change(action,item,extra={}){await run(async()=>{record.value=(await api.change(record.value.id,'action',{revision:record.value.revision,action,item_id:item?.id,...extra})).record})}
async function review(item,approved){try{const {value}=await ElMessageBox.prompt(approved?'可填写复核意见':'请填写退回原因',approved?'复核通过':'退回整改',{inputType:'textarea',inputValidator:v=>approved||!!v?.trim()||'请填写退回原因'});await change(approved?'approve':'reject',item,{note:value})}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}
async function upload(event){const files=[...event.target.files];event.target.value='';await run(async()=>{if(files.length+submission.value.photos.length>9)throw Error('每次最多9张照片');for(const file of files){const out=await api.upload(record.value.id,{size:file.size,mime:file.type.replace('image/',''),read:(offset,length)=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file.slice(offset,offset+length))})});submission.value.photos.push(out.path)}})}
async function submit(){await change('submit',executeItem.value,submission.value);if(record.value.items.find(i=>i.id===executeItem.value?.id)?.status==='pending_review')executeItem.value=null}
async function deleteReport(){await run(async()=>{await api.change(record.value.id,'delete',{revision:record.value.revision,confirmed:true});record.value=null;deleting.value=false;if(route.query.id)await router.replace('/inspections');rows.value=(await api.list()).rows;ElMessage.success('报告已永久删除')})}
async function viewPhoto(path){await run(async()=>{photoUrl.value=(await readTaskPhoto(o=>api.photo(path,'original',Number(new URL('http://local'+o.url).searchParams.get('chunk'))),path)).data;photoOpen.value=true})}
onMounted(load)
